-- 6. Perfiles de veterinario
INSERT INTO perfiles_veterinario (usuario_id, matricula, colegio_emisor, verificado_en)
SELECT id, 'MP-' || (1000 + rn), 'Colegio de Veterinarios de la Provincia de Buenos Aires',
